def __images__(self, fnm, page_from=0, page_to=100, callback=None):
        """Generate page images from PDF for cropping."""
        self.page_from = page_from
        self.page_to = page_to
        try:
            with pdfplumber.open(fnm) if isinstance(fnm, (str, PathLike)) else pdfplumber.open(BytesIO(fnm)) as pdf:
                self.pdf = pdf
                total_pages = len(self.pdf.pages)
                # clamp page range to valid bounds [0, total_pages)
                start = max(0, page_from)
                end = min(page_to, total_pages)
                if start >= end:
                    self.page_images = []
                else:
                    self.page_images = [
                        p.to_image(resolution=72, antialias=True).original
                        for p in self.pdf.pages[start:end]
                    ]
        except Exception as e:
            self.page_images = None
            self.logger.exception(e)

