def output(self, allow_partial=True) -> Tuple[str, Union[pd.DataFrame, partial]]:
        o = getattr(self._param, self._param.output_var_name)

        def _sanitize(df: pd.DataFrame) -> pd.DataFrame:
            # Replace NaN/NaT with None to make it JSON serializable
            return df.where(pd.notnull(df), None)

        if not isinstance(o, partial):
            if not isinstance(o, pd.DataFrame):
                if isinstance(o, list):
                    return self._param.output_var_name, _sanitize(pd.DataFrame(o))
                if o is None:
                    return self._param.output_var_name, pd.DataFrame()
                return self._param.output_var_name, _sanitize(pd.DataFrame([{"content": str(o)}]))
            return self._param.output_var_name, _sanitize(o)

        if allow_partial or not isinstance(o, partial):
            if not isinstance(o, partial) and not isinstance(o, pd.DataFrame):
                return self._param.output_var_name, _sanitize(pd.DataFrame(o if isinstance(o, list) else [o]))
            if isinstance(o, pd.DataFrame):
                return self._param.output_var_name, _sanitize(o)
            return self._param.output_var_name, o

        outs = None
        for oo in o():
            if not isinstance(oo, pd.DataFrame):
                outs = _sanitize(pd.DataFrame(oo if isinstance(oo, list) else [oo]))
            else:
                outs = _sanitize(oo)
        return self._param.output_var_name, outs

