@classmethod
@DB.connection_context()
def remove_document(cls, doc, tenant_id):
    cls.clear_chunk_num(doc.id)

    def _escape(v):
        if isinstance(v, str):
            return v.replace("'", "''")
        if isinstance(v, list):
            return [i.replace("'", "''") if isinstance(i, str) else i for i in v]
        return v

    try:
        settings.docStoreConn.delete(
            {"doc_id": _escape(doc.id)},
            search.index_name(tenant_id),
            doc.kb_id
        )

        settings.docStoreConn.update(
            {
                "kb_id": _escape(doc.kb_id),
                "knowledge_graph_kwd": ["entity", "relation", "graph", "community_report"],
                "source_id": _escape(doc.id)
            },
            {"remove": {"source_id": _escape(doc.id)}},
            search.index_name(tenant_id),
            doc.kb_id
        )

        settings.docStoreConn.update(
            {
                "kb_id": _escape(doc.kb_id),
                "knowledge_graph_kwd": ["graph"]
            },
            {"removed_kwd": "Y"},
            search.index_name(tenant_id),
            doc.kb_id
        )

        settings.docStoreConn.delete(
            {
                "kb_id": _escape(doc.kb_id),
                "knowledge_graph_kwd": ["entity", "relation", "graph", "community_report"],
                "must_not": {"exists": "source_id"}
            },
            search.index_name(tenant_id),
            doc.kb_id
        )
    except Exception:
        pass

    return cls.delete_by_id(doc.id)

