def split_with_pattern(d, pattern: str, content: str, eng) -> list:
    docs = []
    try:
        txts = [txt for txt in re.split(r"(%s)" % pattern, content, flags=re.DOTALL)]
    except re.error:
        txts = [content]
    for j in range(0, len(txts), 2):
        txt = txts[j]
        if not txt:
            continue
        if j + 1 < len(txts):
            txt += txts[j + 1]
        dd = copy.deepcopy(d)
        tokenize(dd, txt, eng)
        docs.append(dd)
    return docs

