def increase_usage(cls, tenant_id, llm_type, used_tokens, llm_name=None):
        e, tenant = TenantService.get_by_id(tenant_id)
        if not e:
            raise LookupError("Tenant not found")

        if llm_type == LLMType.EMBEDDING.value:
            mdlnm = tenant.embd_id
        elif llm_type == LLMType.SPEECH2TEXT.value:
            mdlnm = tenant.asr_id
        elif llm_type == LLMType.IMAGE2TEXT.value:
            mdlnm = tenant.img2txt_id
        elif llm_type == LLMType.CHAT.value:
            mdlnm = tenant.llm_id if not llm_name else llm_name
        elif llm_type == LLMType.RERANK:
            mdlnm = tenant.rerank_id if not llm_name else llm_name
        elif llm_type == LLMType.TTS:
            mdlnm = tenant.tts_id if not llm_name else llm_name
        else:
            assert False, "LLM type error"

        if not mdlnm:
            return 0

        llm_name = mdlnm.split("@")[0] if "@" in mdlnm else mdlnm

        num = 0
        try:
            updated = False
            for u in cls.query(tenant_id=tenant_id, llm_name=llm_name):
                num += cls.model.update(used_tokens=u.used_tokens + used_tokens)\
                    .where(cls.model.tenant_id == tenant_id, cls.model.llm_name == llm_name)\
                    .execute()
                updated = True
            if not updated:
                num += cls.model.create(
                    tenant_id=tenant_id,
                    llm_name=llm_name,
                    used_tokens=used_tokens
                )
        except Exception:
            pass
        return num

