            return {}

def change_password(self, user_id, password, password_confirm):
        try:
            from ktem.pages.admin.user import validate_password
        except ModuleNotFoundError:
            def validate_password(pw, pw_confirm):
                errors = []
                if not pw or not pw_confirm:
                    errors.append("Password cannot be empty")
                if pw != pw_confirm:
                    errors.append("Passwords do not match")
                return errors

        errors = validate_password(password, password_confirm)
        if errors:
            print(errors)
            gr.Warning(errors)
            return password, password_confirm

        with Session(engine) as session:
            statement = select(User).where(User.id == user_id)
            result = session.exec(statement).all()
            if result:
                user = result[0]
                hashed_password = hashlib.sha256(password.encode()).hexdigest()
                user.password = hashed_password
                session.add(user)
                session.commit()
                gr.Info("Password changed")
            else:
                gr.Warning("User not found")

        return "", ""

