const valToStr = (val: any, isQuoted = false) => {
      if (val === undefined) return 'null';
      if (val === null) return 'null';

      if (typeof val === 'object') return JSON.stringify(val);

      if (typeof val === 'string') {
        // escape special characters like newline to keep valid JSON
        const escapedVal = val
          .replace(/\\/g, '\\\\')
          .replace(/\n/g, '\\n')
          .replace(/\r/g, '\\r')
          .replace(/\t/g, '\\t');

        if (isQuoted) {
          return escapedVal.replace(/(?<!\\)"/g, '\\"');
        }
        try {
          JSON.parse(escapedVal);
          return escapedVal;
        } catch (error) {
          const str = JSON.stringify(escapedVal);
          return str.startsWith('"') && str.endsWith('"') ? str.slice(1, -1) : str;
        }
      }

