async copyObjectInSelfBucket(params: CopyObjectParams): Promise<CopyObjectResult> {
    const { sourceKey, targetKey } = params;

    const encodedSourceKey = sourceKey
      .split('/')
      .map((segment) => encodeURIComponent(segment))
      .join('/');

    const requestParams = (this.client as any)._objectRequestParams('PUT', targetKey, {});
    requestParams.headers = requestParams.headers || {};
    requestParams.headers['x-oss-copy-source'] = `/${this.options.bucket}/${encodedSourceKey}`;
    requestParams.xmlResponse = true;
    requestParams.successStatuses = [200, 304];

    await (this.client as any).request(requestParams);

    return {
      bucket: this.options.bucket,
      sourceKey,
      targetKey
    };
  }

