export function formatDate(dateString) {
  const date = isNaN(new Date(dateString).getTime())
    ? new Date()
    : new Date(dateString);
  const options = { year: "numeric", month: "short", day: "numeric" };
  const formattedDate = date.toLocaleDateString("en-US", options);
  return formattedDate;
}

export function getFileExtension(path) {
  return path?.split(".")?.slice(-1)?.[0] || "file";
}

export function middleTruncate(str, n) {
  if (!str) return "";
  const fileExtensionPattern = /(\..+)$/;
  const extensionMatch = str.match(fileExtensionPattern);

  if (str.length <= n) return str;

  // ensure truncation keeps UI compact to avoid overlapping clickable elements
  const safeN = Math.max(10, n);

  if (extensionMatch && extensionMatch[1]) {
    const extension = extensionMatch[1];
    const nameWithoutExtension = str.replace(fileExtensionPattern, "");

    const truncationPoint = Math.max(0, safeN - extension.length - 5);
    const tailLength = Math.min(4, nameWithoutExtension.length);

    const truncatedName =
      nameWithoutExtension.slice(0, truncationPoint) +
      "..." +
      nameWithoutExtension.slice(-tailLength);

    return truncatedName + extension;
  } else {
    const headLength = Math.max(0, safeN - 7);
    const tailLength = Math.min(4, str.length);
    return str.slice(0, headLength) + "..." + str.slice(-tailLength);
  }
}

