  if (fetchResponse.pipeline !== null) {
    this._pipeline = fetchResponse.pipeline;
    this.modelDownloaded = true;
    return this._pipeline;
  }

  this.log(
    `Failed to download model from primary URL. Using fallback ${fetchResponse.retry}`
